-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ruRU" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.deathknight.blood.Name"] = "Рекомендуемая"
L["rm.mop.deathknight.blood.Description"] = "Рекомендуется для танков «Крови»; выбирается при специализации «Кровь». Начинает бой с дистанции Вспышкой болезни, Ледяным прикосновением или Хваткой смерти. Удар смерти при здоровье ниже половины, всякий раз, когда нет Щита крови (с 80 уровня), и до того, как все четыре руны льда и нечестивости окажутся заполнены; Рунический удар около 90 ед. силы рун (Лик смерти при 80, пока вы его не изучили); Вспышка болезни, иначе Ледяное прикосновение и Удар чумы для болезней, и Вскипание крови для их обновления с 68 уровня; Жнец душ ниже 35%; Удар в сердце (до 60 уровня — Кровавый удар) при двух рунах крови; Алая Плеть на Смерть и разложение, пока держатся болезни, иначе Вскипание крови; Кровоотвод при одиннадцати зарядах; затем Удар смерти, Удар в сердце, Рунический удар и Зимний горн. Три врага рядом с вами: Смерть и разложение, распространение болезней (Вскипание крови с Мутной кровью, иначе Мор) и Вскипание крови. Напоминания: Власть крови, если у вас нет власти, Костяной щит, Зимний горн, Заморозка разума, Захват рун, Кровь вампира, Незыблемость льда, Усиление рунического оружия и Смертельный союз в зависимости от вашего здоровья, Танцующее руническое оружие против элитных противников, Войско мертвых перед боссом в группе. Ротация не видит входящий урон, поэтому Антимагический панцирь (выключен) и крупные защитные способности — за вами."
L["rm.mop.deathknight.blood.simulator.Name"] = "По здоровью (симулятор)"
L["rm.mop.deathknight.blood.simulator.Description"] = "Альтернатива рекомендуемой встроенной ротации «Кровь» для рейдовых танков с лекарями, по умолчанию выключена: включите её и выключите ту или повысьте её приоритет. Удар смерти только при здоровье ниже 70%, когда Щита крови нет или он вот-вот спадёт, или до переполнения рун льда и нечестивости, а не на каждой руне; одиночная руна крови уходит на Удар в сердце, когда до рун льда и нечестивости больше секунды. Раздела для нескольких целей нет, напоминания те же, что и в рекомендуемой ротации."
L["rm.mop.deathknight.frost.Name"] = "Двуручное оружие"
L["rm.mop.deathknight.frost.Description"] = "«Лед» с двуручным оружием, обычный вариант для прокачки; выбирается при специализации «Лед», если не подходит встроенная ротация для двух оружий. То же начало боя, болезни, выживание и AoE, что и во встроенной ротации для двух оружий, затем Уничтожение при Машине для убийств, Ледяной удар выше 76 ед. силы рун, Воющий ветер при Инее, Уничтожение всякий раз, когда заполнена пара рун, Уничтожение, Воющий ветер, Вытягивание чумы, Ледяной удар при 40 и Зимний горн. До Уничтожения (58 уровень) руны нечестивости тратит Удар смерти. Те же напоминания, что и во встроенной ротации для двух оружий."
L["rm.mop.deathknight.frost.dualwield.Name"] = "Два оружия"
L["rm.mop.deathknight.frost.dualwield.Description"] = "Рекомендуется для «Льда» с двумя одноручными оружиями (Masterfrost); выбирается при специализации «Лед», пока в левой руке оружие. Начинает бой Вспышкой болезни или Воющим ветром (в одиночной игре — Хваткой смерти). Удар смерти при Темной опеке или здоровье ниже 35%, Кровоотвод при одиннадцати зарядах, болезни (Нечестивая порча, Вспышка болезни, Воющий ветер, Удар чумы), Жнец душ ниже 35%, Ледяной удар при Машине для убийств или выше 89 ед. силы рун, Воющий ветер при Инее или при готовых обеих рунах льда или обеих рунах смерти, Уничтожение при двух рунах нечестивости ниже 77 ед. силы рун, Ледяной удар выше 76, Уничтожение, Воющий ветер, Вытягивание чумы до того, как болезни спадут, при готовой Вспышке болезни, Ледяной удар при 40, Зимний горн. Три врага рядом с вами: распространение болезней, Смерть и разложение и Воющий ветер. Напоминания: Власть льда, Ледяной столп, Воскрешение мертвых, Усиление рунического оружия, когда все руны истрачены, Зимний горн, Заморозка разума, Незыблемость льда и Смертельный союз при низком здоровье, Войско мертвых перед боссом в группе."
L["rm.mop.deathknight.unholy.Name"] = "Нечестивость"
L["rm.mop.deathknight.unholy.Description"] = "Рекомендуется для «Нечестивости»; также встроенная ротация для любого рыцаря смерти, которого не забирают «Кровь» и «Лед», в том числе без специализации. Начинает бой с дистанции Вспышкой болезни или Ледяным прикосновением (в одиночной игре — Хваткой смерти). Удар смерти при Темной опеке или здоровье ниже 35%, болезни (Нечестивая порча, Вспышка болезни, Удар чумы, Ледяное прикосновение), Кровоотвод при одиннадцати зарядах, Жнец душ ниже 35%, Темное превращение при пяти наложениях Вливания Тьмы, Лик смерти у предела силы рун, Смерть и разложение по цели, которая проживёт достаточно долго, Удар Плети, Лик смерти при Неумолимом роке или при 40, Вспышка болезни, пока действует Нечестивая сила, Удар разложения (Кровавый удар, пока вы его не изучили), Вытягивание чумы, Зимний горн. Три врага рядом с вами: распространение болезней, Смерть и разложение, Вскипание крови и Ледяное прикосновение на руне льда. Напоминания: Власть нечестивости, ваш вурдалак, Призыв горгульи под Жаждой крови или в долгом бою с элитным противником, Нечестивое бешенство, Усиление рунического оружия, Зимний горн, Заморозка разума, Незыблемость льда и Смертельный союз при низком здоровье, Войско мертвых перед боссом в группе; Антимагический панцирь выключен."
L["rm.mop.deathknight.unholy.simulator.Name"] = "Нечестивость, накопление до предела рун (симулятор)"
L["rm.mop.deathknight.unholy.simulator.Description"] = "Альтернатива рекомендуемой встроенной ротации «Нечестивость» — так её играют симулятор, wowtbc.gg, Method и MaxDps; по умолчанию выключена: включите её и выключите ту или повысьте её приоритет. Пока Темное превращение не действует, Лик смерти идёт на восстановление Вливания Тьмы, Удар Плети идёт первым, когда готовы обе руны нечестивости или обе руны смерти, а Удар разложения — первым, когда готовы обе руны крови и обе руны льда; в остальном то же начало боя, болезни, AoE и напоминания, что и в рекомендуемой ротации."
L["rm.retail.deathknight.blood.Name"] = "Боевой помощник Blizzard"
L["rm.retail.deathknight.blood.Description"] = "Рекомендуется для специализации «Кровь». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что Боевой помощник оставляет вам: Кровь вампира и Воскрешение мертвых в бою, Заморозка разума против прерываемого заклинания, Незыблемость льда и ваша расовая способность, как только они готовы в бою. В бою заклинания противников скрыты, поэтому Заморозка разума загорается только там, где игра их показывает; на Retail здоровье скрыто, поэтому момент для Незыблемости льда — на ваше усмотрение. За вами остаются: выбор момента для активной защиты, Антимагический панцирь, провокации и аксессуары."
L["rm.retail.deathknight.blood.guide.Name"] = "Для справки (Icy Veins и Wowhead)"
L["rm.retail.deathknight.blood.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет «Крови» по руководствам. В бою в Midnight ваши положительные и отрицательные эффекты на цели скрыты от аддонов, поэтому шаги, которые их читают, там ждут; читайте её или продублируйте, чтобы поэкспериментировать. На Retail здоровье и сила рун скрыты, поэтому Удар смерти применяется, когда хватает силы рун. Начало боя: Прикосновение смерти. Удар смерти; Дробление хребта (Прикосновение смерти вне ближнего боя), когда Костяного щита нет, у него меньше пяти зарядов, он вот-вот спадёт или действует Истребление; во время Дара сан'лейн — Удар смерти, одно Вскипание крови, Смерть и разложение при срабатывании Алой Плети и Удар в сердце; Смерть и разложение при срабатывании Алой Плети или против четырёх врагов; Удар вампира; Поглощение; Вскипание крови при Точке кипения, отсутствии Кровавой чумы или полных зарядах; Удар в сердце. Напоминания: Воскрешение мертвых, Кровь вампира, Метка жнеца, Танцующее руническое оружие после Метки жнеца, а также вспомогательные напоминания встроенной ротации с Боевым помощником."
L["rm.retail.deathknight.blood.simc.Name"] = "Вестник Смерти, для справки (SimulationCraft)"
L["rm.retail.deathknight.blood.simc.Description"] = "Только для справки, по умолчанию выключена: список SimulationCraft для Вестника Смерти, который тратит силу рун на Удар смерти ради урона. Скрытые боевые данные не дают ей работать в бою в Midnight, а сила рун на Retail скрыта, поэтому сброса на пределе нет. Смерть и разложение всякий раз, когда она не действует, Метка жнеца, Дробление хребта при Истреблении, Прикосновение смерти ради Костяного щита, пока не хватает рун (иначе Дробление хребта), Удар смерти, Вскипание крови, Поглощение вне Танцующего рунического оружия, Удар в сердце. Напоминания: Воскрешение мертвых, Танцующее руническое оружие, Кровь вампира и вспомогательные напоминания."
L["rm.retail.deathknight.frost.Name"] = "Боевой помощник Blizzard"
L["rm.retail.deathknight.frost.Description"] = "Рекомендуется для специализации «Лед». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — напоминания о том, что Боевой помощник оставляет вам: Дыхание Синдрагосы и Воскрешение мертвых в бою, Заморозка разума против прерываемого заклинания, Незыблемость льда и ваша расовая способность, как только они готовы в бою. В бою заклинания противников скрыты, поэтому Заморозка разума загорается только там, где игра их показывает; на Retail здоровье скрыто, поэтому момент для Незыблемости льда — на ваше усмотрение."
L["rm.retail.deathknight.frost.guide.Name"] = "Для справки (Icy Veins и SimulationCraft)"
L["rm.retail.deathknight.frost.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет «Льда» по руководствам. Машина для убийств, Иней и Режущий лед скрыты в бою в Midnight, поэтому ротация не может там работать; сила рун на Retail скрыта, поэтому проверки максимума нет. Уничтожение при двух зарядах Машины для убийств или при одном и трёх рунах, Ледяной удар при пяти наложениях Режущего льда с Сокрушительным клинком, Воющий ветер при Инее, Уничтожение при Машине для убийств, Ледяной удар, Уничтожение; против трёх и более врагов в ход идут Ледяная коса и Ледяной натиск; Воющий ветер вне ближнего боя. Напоминания: Беспощадность зимы, Ледяной столп, Дыхание Синдрагосы и Ярость ледяного змея под Ледяным столпом, Метка жнеца, Воскрешение мертвых, Усиление рунического оружия при двух зарядах, а также вспомогательные напоминания."
L["rm.retail.deathknight.frost.wowhead.Name"] = "Для справки (Wowhead)"
L["rm.retail.deathknight.frost.wowhead.Description"] = "Только для справки, по умолчанию выключена: порядок «Льда» по Wowhead, который ставит способности с восстановлением прямо в ротацию. Скрытые боевые данные не дают этой ротации работать в бою в Midnight; сила рун на Retail скрыта, поэтому проверки максимума нет. Усиление рунического оружия при двух зарядах, Метка жнеца, Ледяной столп, Дыхание Синдрагосы, Ярость ледяного змея; затем Уничтожение при двух зарядах Машины для убийств или при одном с Истреблением, Воющий ветер при Инее, Уничтожение при Машине для убийств, Усиление рунического оружия ради нового заряда, Ледяной удар, Уничтожение, Воющий ветер. Против трёх и более врагов в ход идут Ледяная коса и Ледяной натиск."
L["rm.retail.deathknight.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.deathknight.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию рыцаря смерти). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций рыцаря смерти, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.retail.deathknight.unholy.Name"] = "Боевой помощник Blizzard"
L["rm.retail.deathknight.unholy.Description"] = "Рекомендуется для специализации «Нечестивость». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight (он сам поднимает вашего вурдалака и применяет Войско мертвых и Темное превращение); пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним: Заморозка разума против прерываемого заклинания, а также Незыблемость льда и ваша расовая способность, как только они готовы в бою. В бою заклинания противников скрыты, поэтому Заморозка разума загорается только там, где игра их показывает; на Retail здоровье скрыто, поэтому момент для Незыблемости льда — на ваше усмотрение."
L["rm.retail.deathknight.unholy.guide.Name"] = "Для справки (Icy Veins и Wowhead)"
L["rm.retail.deathknight.unholy.guide.Description"] = "Только для справки, по умолчанию выключена: приоритет «Нечестивости» по руководствам. Срабатывания и болезни скрыты в бою в Midnight, поэтому ротация не может там работать; сила рун и здоровье цели на Retail скрыты, поэтому окно добивания и трата силы рун для Сан'лейн опущены. Воскрешение мертвых, если нет вурдалака; Гнойная коса, чтобы поддерживать ускорение от её болезни; Жнец душ при Жатве; Нагноение во время Темного превращения; Лик смерти (Эпидемия против четырёх и более врагов) при Неумолимом роке или Запретном знании; Удар разложения, если нет зарядов Мелкого вурдалака, Удар Плети, если они есть; Лик смерти. Напоминания: Войско мертвых, Темное превращение, Вспышка болезни, когда нет ваших болезней, а также вспомогательные напоминания."
L["rm.retail.deathknight.unholy.simc.Name"] = "Для справки (SimulationCraft)"
L["rm.retail.deathknight.unholy.simc.Description"] = "Только для справки, по умолчанию выключена: список SimulationCraft для «Нечестивости», где Лик смерти применяется гораздо чаще. Скрытые боевые данные не дают этой ротации работать в бою в Midnight; сила рун и здоровье цели на Retail скрыты, поэтому проверки максимума и добивания опущены. Поддержание Гнойной косы, Жнец душ во время Темного превращения, Лик смерти при Неумолимом роке, Нагноение во время Темного превращения, Лик смерти во время Темного превращения или Запретного знания и всякий раз, когда до Войска мертвых больше 5 секунд, Удар Плети при зарядах Мелкого вурдалака, Удар разложения. Против трёх и более врагов: Эпидемия вместо Лика смерти и Удар разложения при менее чем трёх зарядах. Напоминания: Вспышка болезни, Смерть и разложение против групп врагов, Войско мертвых, Темное превращение."
